type BlacklistItem = { id: number; discordUserId: string; reason: string | null; active: number };
type PublishedTxtItem = { id: number; ownerId: number; ownerName: string; ownerOpenId: string | null; discordUserId: string | null; discordUsername: string | null; name: string; description: string; slug: string; source: string; sourceSize: number; sourceHash: string; createdAt: string; updatedAt: string };

function navIcon(kind: string) {
  if (kind === "overview") return <LayoutDashboard size={16} />;
  if (kind === "scripts") return <FolderCode size={16} />;
  if (kind === "obfuscator") return <Code2 size={16} />;
  if (kind === "keys") return <KeyRound size={16} />;
  if (kind === "hwid") return <ShieldCheck size={16} />;
  if (kind === "logs") return <FileText size={16} />;
  if (kind === "prices") return <ReceiptText size={16} />;
  if (kind === "plans") return <KeyRound size={16} />;
  if (kind === "settings") return <Settings2 size={16} />;
  return <LayoutDashboard size={16} />;
}

function downloadText(filename: string, value: string) {
  const blob = new Blob([value], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

function encodeBytesBase64(bytes: Uint8Array) {
  let binary = "";
  for (let index = 0; index < bytes.length; index += 0x8000) {
    const chunk = bytes.subarray(index, index + 0x8000);
    for (let offset = 0; offset < chunk.length; offset += 1) binary += String.fromCharCode(chunk[offset]);
  }
  return btoa(binary);
}

export function encodeSourceBase64(source: string) {
  return encodeBytesBase64(new TextEncoder().encode(source));
}

export async function encodeSourceGzipBase64(source: string) {
  if (typeof CompressionStream === "undefined") return encodeSourceBase64(source);
  const compressed = await new Response(new Blob([source]).stream().pipeThrough(new CompressionStream("gzip"))).arrayBuffer();
  return encodeBytesBase64(new Uint8Array(compressed));
}

export function friendlyApiError(error: unknown, fallback: string) {
  const message = error instanceof Error ? error.message : String(error ?? "");
  if (/Unexpected token ['\"]?</.test(message) || /not valid JSON/i.test(message)) {
    return "El servidor devolvió una respuesta inválida. Recarga la página e inténtalo de nuevo; si continúa, prueba desde el dominio publicado.";
  }
  return message || fallback;
}

async function copyText(value: string) {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(value);
    } else {
      const helper = document.createElement("textarea");
      helper.value = value;
      helper.setAttribute("readonly", "");
      helper.style.position = "fixed";
      helper.style.opacity = "0";
      document.body.appendChild(helper);
      helper.select();
      document.execCommand("copy");
      helper.remove();
    }
    toast.success("Copiado al portapapeles");
  } catch {
    toast.error("No se pudo copiar; mantén presionado el código para copiarlo");
  }
}

function CopyButton({ value, label = "Copy" }: { value: string; label?: string }) {
  return <button className="icon-copy" onClick={() => void copyText(value)} aria-label={label} title={label}><Copy size={15} /></button>;
}

function MobileViewScriptButton({ value }: { value: string }) {
  return <button className="mobile-view-script" type="button" onClick={() => void copyText(value)}><Copy size={14} /> Mobile View Script</button>;
}

